    Returns:
        str: The string representation of the polynomial.
    """
    terms = []
    for idx, coeff in enumerate(coeffs):
        degree = n - idx
        if coeff == 0:
            continue

        # Determine sign: '+' for positive terms after the first, no sign for first positive term,
        # '-' for negative terms (with '-' for first negative term as well).
        if coeff > 0:
            sign = '' if not terms else '+'
        else:
            sign = '' if not terms else '-'
            if not terms:  # first term is negative
                sign = '-'

        abs_coeff = abs(coeff)

        # Build variable part
        if degree == 0:
            var_part = ''
        elif degree == 1:
            var_part = 'x'
        else:
            var_part = f'x^{degree}'

        # Build coefficient representation
        if degree == 0:
            coeff_str = str(abs_coeff)
        else:
            if abs_coeff == 1:
                coeff_str = ''
            else:
                coeff_str = str(abs_coeff)

        term = f"{sign}{coeff_str}{var_part}"
        terms.append(term)

    if not terms:
        return '0'
    return ''.join(terms)

