def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of pairs of positive integers (P, Q) such that
    P and Q have x0 as their greatest common divisor (GCD) and y0 as
    their least common multiple (LCM).
    """
    # Basic input validation
    if x0 <= 0 or y0 <= 0:
        return 0
    if y0 % x0 != 0:
        return 0

    k = y0 // x0

    # Euclidean algorithm for gcd
    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    count = 0
    i = 1
    while i * i <= k:
        if k % i == 0:
            a = i
            b = k // i
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
        i += 1

    return count

def preorder_traversal(inorder: str, postorder: str) -> str:
    """
    Reconstructs the binary tree from its inorder and postorder traversals and
    returns the preorder traversal as a string.

    Args:
        inorder (str): The inorder traversal of the binary tree.
        postorder (str): The postorder traversal of the binary tree.

    Returns:
        str: The preorder traversal of the binary tree.

    Raises:
        ValueError: If input lengths differ, or if characters are missing.
    """
    if not inorder and not postorder:
        return ''
    if len(inorder) != len(postorder):
        raise ValueError("Inorder and postorder strings must be of equal length.")
    # Map each character to its index in inorder for O(1) lookups
    try:
        index_map = {ch: i for i, ch in enumerate(inorder)}
    except Exception as exc:
        raise ValueError(f"Failed to build index map: {exc}") from exc

    def helper(in_start: int, in_end: int, post_start: int, post_end: int) -> str:
        if in_start > in_end:
            return ''
        # Root is always the last element in the current postorder slice
        root = postorder[post_end]
        if root not in index_map:
            raise ValueError(f"Character '{root}' not found in inorder traversal.")
        in_root_idx = index_map[root]
        if in_root_idx < in_start or in_root_idx > in_end:
            raise ValueError(f"Character '{root}' is outside the current inorder slice.")
        left_size = in_root_idx - in_start

        left_pre = ''
        right_pre = ''
        if left_size > 0:
            # Left subtree: inorder[in_start:in_root_idx-1], postorder[post_start:post_start+left_size-1]
            left_pre = helper(in_start, in_root_idx - 1, post_start, post_start + left_size - 1)
        if in_root_idx < in_end:
            # Right subtree: inorder[in_root_idx+1:in_end], postorder[post_start+left_size:post_end-1]
            right_pre = helper(in_root_idx + 1, in_end, post_start + left_size, post_end - 1)

        return root + left_pre + right_pre

    return helper(0, len(inorder) - 1, 0, len(postorder) - 1)

def preorder_traversal(inorder: str, postorder: str) -> str:
    """Reconstruct a binary tree from inorder and postorder traversals and
    return its preorder traversal as a string."""
    if inorder is None or postorder is None:
        raise TypeError("inorder and postorder must not be None")

    n = len(inorder)
    if len(postorder) != n:
        raise ValueError("inorder and postorder must have the same length")

    if n == 0:
        return ''

    # Map each value to its index in inorder for O(1) lookups
    index_map = {}
    for idx, val in enumerate(inorder):
        if val in index_map:
            raise ValueError("Duplicate values found in inorder traversal")
        index_map[val] = idx

    def helper(in_left: int, in_right: int, post_left: int, post_right: int) -> str:
        if in_left > in_right:
            return ''
        root_val = postorder[post_right]
        if root_val not in index_map:
            raise ValueError(f"Value '{root_val}' from postorder not present in inorder")
        root_index = index_map[root_val]
        left_size = root_index - in_left

        # Recursively build left and right subtrees
        left_pre = helper(
            in_left,
            root_index - 1,
            post_left,
            post_left + left_size - 1
        )
        right_pre = helper(
            root_index + 1,
            in_right,
            post_left + left_size,
            post_right - 1
        )
        return root_val + left_pre + right_pre

    return helper(0, n - 1, 0, n - 1)

