def calculate_score(system: int, points: str) -> list:
    """
    Calculate the ping-pong game scores from a sequence of points.

    :param system: The number of points required to win a game (either 11 or 21).
    :param points: A string consisting of 'W' and 'L' characters indicating points won by the player and the opponent.
    :return: A list of strings in the format "player_score:opponent_score" for each completed game and any unfinished game at the end.
    """
    if system not in (11, 21):
        raise ValueError("System must be either 11 or 21 points.")
    if not isinstance(points, str):
        raise TypeError("Points must be provided as a string.")
    scores = []
    player_score = 0
    opponent_score = 0

    for ch in points:
        if ch == 'W':
            player_score += 1
        elif ch == 'L':
            opponent_score += 1
        else:
            raise ValueError("Points string must contain only 'W' and 'L' characters.")

        # Check if the game is finished
        if (player_score >= system or opponent_score >= system) and abs(player_score - opponent_score) >= 2:
            scores.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0

    # Include any unfinished game at the end of the sequence
    if player_score > 0 or opponent_score > 0:
        scores.append(f"{player_score}:{opponent_score}")

    return scores

