def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    if n < 0 or m < 0 or len(a) != n:
        return 0
    if sum(a) < m:
        return 0
    prev = [0] * (m + 1)
    prev[0] = 1
    for limit in a:
        curr = [0] * (m + 1)
        prefix = [0] * (m + 1)
        prefix[0] = prev[0]
        for s in range(1, m + 1):
            prefix[s] = (prefix[s - 1] + prev[s]) % MOD
        for s in range(m + 1):
            low = s - limit
            if low <= 0:
                curr[s] = prefix[s]
            else:
                curr[s] = (prefix[s] - prefix[low - 1]) % MOD
        prev = curr
    return prev[m] % MOD

