        if inc[i] > 1 and dec[i] > 1:
            mountain_len = inc[i] + dec[i] - 1
            if mountain_len > max_len:
                max_len = mountain_len

    # If no mountain of length >=3 is possible, we can keep at most one student
    if max_len == 0:
        max_len = 1

    return n - max_len

